$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
. (Join-Path $PSScriptRoot 'custom-app-production-real-pc-recovery-dispatcher.ps1')
function Assert-RDTrue([bool]$v,[string]$m){if(-not $v){throw $m}}
function Assert-RDFalse([bool]$v,[string]$m){if($v){throw $m}}
function Assert-RDEq($a,$e,[string]$m){if([string]$a-cne[string]$e){throw "$m actual=<$a> expected=<$e>"}}
function Copy-RD($o){return (($o|ConvertTo-Json -Depth 60)|ConvertFrom-Json)}

$script:RDMode='valid';$script:RDPhase='rollback-required';$script:RDRevision=[int64]4;$script:RDSha=('4'*64);$script:RDTx=('a'*64);$script:RDLTree=('b'*64);$script:RDPersist=('c'*64);$script:RDGenericFp=('d'*64);$script:RDExecCalls=0;$script:RDReadCalls=0;$script:RDProfile=$null;$script:RDLive=$null;$script:RDRoot=$null
function Get-SpicetifyAssetRoots{param([string]$Kind);if($script:RDMode-ceq'root-mismatch'){return @((Join-Path $script:RDProfile 'OtherApps'))};return @($script:RDRoot)}
function Read-CustomAppProductionCrashJournalV010{
 param([string]$AllowedRoot,[string]$StoreDirectory);$script:RDReadCalls++
 $phase=$script:RDPhase;$rev=$script:RDRevision;$sha=$script:RDSha;$tx=$script:RDTx
 if($script:RDMode-ceq'journal-null'){return $null};if($script:RDMode-ceq'journal-tx-drift'){$tx=('9'*64)}
 $tr=Join-Path $script:RDProfile 'AppData\Local\SpotifyControl\custom-app-production\transactions\txn';$sw=Join-Path $script:RDProfile 'AppData\Local\SpotifyControl\custom-app-production\stage\11111111111111111111111111111111';$ab=Join-Path $script:RDProfile 'AppData\Local\SpotifyControl\custom-app-production\backups\22222222222222222222222222222222\app-code';$pb=Join-Path $script:RDProfile 'AppData\Local\SpotifyControl\custom-app-production\persistence\txn-20261102-000000-12345678'
 if($script:RDMode-ceq'journal-path-escape'){$tr='C:\escape\txn'}
 $entry=[pscustomobject]@{transaction_id=$tx;phase=$phase;name='tagify';entry_sha256=$sha;live_path=$script:RDLive;transaction_root=$tr;stage_workspace_path=$sw;app_backup_path=$ab;persistence_backup_path=$pb}
 return [pscustomobject]@{ok=$true;reason='fixture-journal';revision=$rev;entry=$entry;transaction_id=$tx;reloaded_from_persistent_store=($script:RDMode-cne'journal-not-durable')}
}
function Resolve-CustomAppProductionRecoveryRoutingAdmissionV010{
 param([string]$AllowedRoot,[string]$StoreDirectory,[string]$ExpectedTransactionId,[DateTimeOffset]$Now)
 if($script:RDMode-ceq'routing-null'){return $null};if($script:RDMode-ceq'routing-denied'){return [pscustomobject]@{ok=$false;reason='fixture-routing-denied';receipt=$null}}
 $phase=$script:RDPhase;$manual=$phase-in@('prepared','atomic-mutation-starting');$recovery=$phase-in@('live-moved-to-old','candidate-live','transaction-finalized','apply-starting','apply-returned-success-pending-verification','rollback-required');$house=$phase-in@('apply-verified','cleanup-starting');$retire=$phase-ceq'rollback-complete';$newPermit=$phase-in@('rollback-complete','committed-clean')
 $route=$(switch($phase){'prepared'{'prepared-transaction-resolution-required'};'atomic-mutation-starting'{'manual-filesystem-recovery-inspection-required'};'apply-verified'{'bounded-recovery-housekeeping-candidate'};'cleanup-starting'{'bounded-recovery-housekeeping-candidate'};'rollback-complete'{'recovery-artifact-retirement-required'};'committed-clean'{'terminal-new-update-permit-readiness-required'};default{'bounded-recovery-executor-candidate'}})
 $rev=$script:RDRevision;$sha=$script:RDSha;if($script:RDMode-ceq'routing-stale'){$rev++};if($script:RDMode-ceq'routing-stale-sha'){$sha=('8'*64)}
 $r=[pscustomobject]@{phase=$phase;route=$route;journal_revision=$rev;journal_entry_sha256=$sha;requires_manual_resolution=$manual;requires_bounded_recovery_executor=$recovery;requires_bounded_housekeeping=$house;requires_recovery_artifact_retirement=$retire;requires_new_update_permit_readiness=$newPermit;routing_is_authority=($script:RDMode-ceq'routing-authority');execution_authorized=$false;restore_authorized=$false;apply_authorized=$false;cleanup_authorized=$false;permit_issued=$false;production_mutation_authorized=$false}
 if($script:RDMode-ceq'route-unhandled'){$r.requires_bounded_recovery_executor=$false;$r.requires_bounded_housekeeping=$false}
 return [pscustomobject]@{ok=$true;reason='fixture-routing';receipt=$r}
}
function Test-CustomAppProductionRecoveryRoutingAdmissionReceiptV010{param($Receipt,[DateTimeOffset]$Now);if($script:RDMode-ceq'routing-invalid'){return [pscustomobject]@{ok=$false;reason='fixture-routing-invalid'}};return [pscustomobject]@{ok=$true;reason='fixture-routing-valid'}}
function Invoke-CustomAppProductionBoundedRecoveryExecutorV010{
 param($AllowedRoot,$StoreDirectory,$ExpectedTransactionId,$LocalAppDataRoot,$AppDataRoot,$SpicetifyAllowedRoot,$SpicetifyPath,$ExpectedSpicetifySha256,[int]$TimeoutSeconds,[DateTimeOffset]$Now)
 $script:RDExecCalls++;if($script:RDMode-ceq'executor-null'){return $null};if($script:RDMode-ceq'executor-denied'){return [pscustomobject]@{ok=$false;reason='fixture-executor-denied';result=$null}}
 $final=$(if($script:RDPhase-in@('apply-verified','cleanup-starting')){'committed-clean'}else{'rollback-complete'});$script:RDPhase=$final;$script:RDRevision=[int64]($script:RDRevision+2);$script:RDSha=('e'*64)
 if($script:RDMode-ceq'post-nonterminal'){$script:RDPhase='cleanup-starting'}
 $endRev=$script:RDRevision;$endSha=$script:RDSha;if($script:RDMode-ceq'post-generic-revision-drift'){$endRev++}
 $tree=$(if($script:RDMode-ceq'post-live-drift'){('7'*64)}else{$script:RDLTree});$persist=$(if($script:RDMode-ceq'post-persistence-drift'){('6'*64)}else{$script:RDPersist})
 $g=[pscustomobject]@{result_fingerprint=$script:RDGenericFp;fixture_only_contract=$true;final_phase=$final;journal_end_revision=$endRev;journal_end_sha256=$endSha;live_runtime_tree_sha256=$tree;persistence_fingerprint=$persist}
 return [pscustomobject]@{ok=$true;reason='fixture-executor-success';result=$g}
}
function Test-CustomAppProductionBoundedRecoveryExecutorResultV010{param($Result);if($script:RDMode-ceq'executor-invalid'){return [pscustomobject]@{ok=$false;reason='fixture-executor-result-invalid'}};return [pscustomobject]@{ok=$true;reason='fixture-executor-result-valid'}}
function Get-CustomAppLocalRuntimeBaseline{param([string]$Name,[string]$AppPath);$tree=$script:RDLTree;if($script:RDMode-ceq'post-live-drift'){$tree=('5'*64)};return [pscustomobject]@{safe=$true;installable=$true;tree_sha256=$tree;manifest_name='Tagify';path=$AppPath}}
function Get-SpotifyPersistenceSnapshot{param([string]$LocalAppDataRoot,[string]$AppDataRoot);$fp=$script:RDPersist;if($script:RDMode-ceq'post-persistence-drift'){$fp=('5'*64)};return [pscustomobject]@{fingerprint=$fp}}

function New-RDFixture([string]$Base){
 $profile=Join-Path $Base 'User';$local=Join-Path $profile 'AppData\Local';$app=Join-Path $profile 'AppData\Roaming';$root=Join-Path $app 'spicetify\CustomApps';$live=Join-Path $root 'tagify';$store=Join-Path $local 'SpotifyControl\custom-app-production\recovery-journal';$spRoot=Join-Path $profile 'spicetify-cli';$sp=Join-Path $spRoot 'spicetify.exe'
 foreach($p in@($profile,$local,$app,$root,$live,$store,$spRoot)){[IO.Directory]::CreateDirectory($p)|Out-Null};[IO.File]::WriteAllText($sp,'fixture-spicetify',[Text.UTF8Encoding]::new($false));$sha=(Get-FileHash $sp -Algorithm SHA256).Hash.ToLowerInvariant();$script:RDProfile=$profile;$script:RDRoot=$root;$script:RDLive=$live;$env:USERPROFILE=$profile;$env:LOCALAPPDATA=$local;$env:APPDATA=$app;return[pscustomobject]@{profile=$profile;local=$local;app=$app;root=$root;live=$live;store=$store;sp=$sp;sha=$sha}
}
function Reset-RD([string]$Mode,[string]$Phase){$script:RDMode=$Mode;$script:RDPhase=$Phase;$script:RDRevision=4;$script:RDSha=('4'*64);$script:RDExecCalls=0;$script:RDReadCalls=0}
function Invoke-RD($F,[string]$Mode='valid',[string]$Phase='rollback-required',[AllowNull()][string]$Profile=$null,[AllowNull()][string]$Store=$null,[AllowNull()][string]$Sp=$null,[AllowNull()][string]$Sha=$null){Reset-RD $Mode $Phase;if([string]::IsNullOrWhiteSpace($Profile)){$Profile=$F.profile};if([string]::IsNullOrWhiteSpace($Store)){$Store=$F.store};if([string]::IsNullOrWhiteSpace($Sp)){$Sp=$F.sp};if([string]::IsNullOrWhiteSpace($Sha)){$Sha=$F.sha};return Invoke-CustomAppProductionRealPcRecoveryDispatcherV010 -ExpectedTransactionId $script:RDTx -UserProfileRoot $Profile -LocalAppDataRoot $F.local -AppDataRoot $F.app -StoreDirectory $Store -SpicetifyPath $Sp -ExpectedSpicetifySha256 $Sha -TimeoutSeconds 10 -Now ([DateTimeOffset]'2026-11-02T00:00:00Z')}
function Assert-RDNoAuthority($R,[string]$L){$x=if($R.PSObject.Properties['result']-and$null-ne$R.result){$R.result}else{$R};foreach($f in@('result_is_authority','routing_is_authority','permit_issued','execution_authorized','restore_authorized','apply_authorized','cleanup_authorized','production_execution_authorized','production_mutation_authorized')){Assert-RDFalse ([bool]$x.$f) "$L escaped $f"}}

$oldProfile=$env:USERPROFILE;$oldLocal=$env:LOCALAPPDATA;$oldApp=$env:APPDATA;$base=Join-Path $env:TEMP ('real-pc-recovery-dispatcher-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($base)|Out-Null
try{
 $f=New-RDFixture $base;$count=0
 foreach($case in@(@('valid','rollback-required','real-pc-recovery-rollback-complete'),@('valid','apply-verified','real-pc-recovery-housekeeping-committed-clean'))){$r=Invoke-RD $f $case[0] $case[1];Assert-RDTrue ([bool]$r.ok) ("$($case[1]) denied "+[string]$r.reason);Assert-RDEq $r.result.status $case[2] 'executor success status';Assert-RDEq $script:RDExecCalls 1 'eligible route executor count';Assert-RDTrue ([bool]$r.result.generic_fixture_contract_verified) 'generic fixture contract not attested';Assert-RDNoAuthority $r $case[1];$vc=Test-CustomAppProductionRealPcRecoveryDispatcherResultV010 $r.result;Assert-RDTrue ([bool]$vc.ok) ('result invalid '+[string]$vc.reason);$count++}
 foreach($phase in@('rollback-complete','committed-clean')){$r=Invoke-RD $f 'valid' $phase;Assert-RDTrue ([bool]$r.ok) ("terminal $phase denied");Assert-RDFalse ([bool]$r.executor_invoked) 'terminal invoked executor';Assert-RDEq $script:RDExecCalls 0 'terminal executor count';Assert-RDTrue ([bool]$r.result.terminal_handoff_required) 'terminal handoff missing';Assert-RDTrue ([bool]$r.result.new_permit_readiness_required) 'terminal new-permit handoff missing';if($phase-ceq'rollback-complete'){Assert-RDTrue ([bool]$r.result.artifact_retirement_required) 'rollback retirement missing'}else{Assert-RDFalse ([bool]$r.result.artifact_retirement_required) 'committed-clean retirement set'};Assert-RDNoAuthority $r $phase;$count++}
 foreach($phase in@('prepared','atomic-mutation-starting')){$r=Invoke-RD $f 'valid' $phase;Assert-RDFalse ([bool]$r.ok) "$phase unexpectedly automated";Assert-RDEq $script:RDExecCalls 0 "$phase executor count";Assert-RDNoAuthority $r $phase;$count++}
 foreach($mode in@('journal-null','journal-not-durable','journal-tx-drift','journal-path-escape','root-mismatch','routing-null','routing-denied','routing-invalid','routing-authority','routing-stale','routing-stale-sha','route-unhandled','executor-null','executor-denied','executor-invalid','post-nonterminal','post-generic-revision-drift','post-live-drift','post-persistence-drift')){$r=Invoke-RD $f $mode 'rollback-required';Assert-RDFalse ([bool]$r.ok) "$mode unexpectedly succeeded";if($mode-in@('executor-null','executor-denied','executor-invalid','post-nonterminal','post-generic-revision-drift','post-live-drift','post-persistence-drift')){Assert-RDEq $script:RDExecCalls 1 "$mode executor count"}else{Assert-RDEq $script:RDExecCalls 0 "$mode executor count"};Assert-RDNoAuthority $r $mode;$count++}
 $wrongProfile=Join-Path $base 'WrongUser';[IO.Directory]::CreateDirectory($wrongProfile)|Out-Null;$r=Invoke-RD $f 'valid' 'rollback-required' $wrongProfile;Assert-RDFalse ([bool]$r.ok) 'foreign profile accepted';Assert-RDEq $script:RDExecCalls 0 'foreign profile executor count';$count++
 $wrongStore=Join-Path $f.local 'SpotifyControl\other-journal';[IO.Directory]::CreateDirectory($wrongStore)|Out-Null;$r=Invoke-RD $f 'valid' 'rollback-required' $null $wrongStore;Assert-RDFalse ([bool]$r.ok) 'wrong store accepted';$count++
 $outside=Join-Path $base 'outside-spicetify.exe';[IO.File]::WriteAllText($outside,'x');$outsideSha=(Get-FileHash $outside -Algorithm SHA256).Hash.ToLowerInvariant();$r=Invoke-RD $f 'valid' 'rollback-required' $null $null $outside $outsideSha;Assert-RDFalse ([bool]$r.ok) 'outside-profile spicetify accepted';$count++
 $r=Invoke-RD $f 'valid' 'rollback-required' $null $null $null ('f'*64);Assert-RDFalse ([bool]$r.ok) 'spicetify hash mismatch accepted';$count++
 $good=Invoke-RD $f 'valid' 'rollback-required';$tamper=Copy-RD $good.result;$tamper.production_mutation_authorized=$true;$tamper.result_fingerprint=Get-CustomAppProductionRealPcRecoveryDispatcherSha256V010(Get-CustomAppProductionRealPcRecoveryDispatcherResultMaterialV010 $tamper);$tc=Test-CustomAppProductionRealPcRecoveryDispatcherResultV010 $tamper;Assert-RDFalse ([bool]$tc.ok) 'rehashed authority tamper accepted';$count++
 $tamper=Copy-RD $good.result;$tamper.result_fingerprint=('9'*64);$tc=Test-CustomAppProductionRealPcRecoveryDispatcherResultV010 $tamper;Assert-RDFalse ([bool]$tc.ok) 'fingerprint tamper accepted';$count++
 Write-Host "CUSTOM_APP_PRODUCTION_REAL_PC_RECOVERY_DISPATCHER_MATRIX_PASS total=$count eligible_executor_exactly_once=true manual_never_executes=true terminal_handoff_no_executor=true stale_routing_denied=true user_profile_bound=true spicetify_sha_bound=true post_journal_live_persistence_reverified=true generic_fixture_contract_internal_only=true zero_authority=true"
}finally{$env:USERPROFILE=$oldProfile;$env:LOCALAPPDATA=$oldLocal;$env:APPDATA=$oldApp;if(Test-Path -LiteralPath $base){[IO.Directory]::Delete($base,$true)}}
